dict.string:
.navbar {
font-family: Verdana, sans-serif;
font-size: .75em;
color: #007398;
line-height: 20px;
text-align: center;
font-weight: bold;
}

.navbar-bg { }

.navbar ul {
list-style: none;
margin: 0px;
padding: 7px 7px 0px 7px;
}

.navbar li {
display: inline;
padding: 20px;

}

.navbar a {
text-decoration: none;
color: #007398;
padding: 10px 0px 10px 0px;
}

.navbar a:visited {
text-decoration: none;
color: #007398;
padding: 10px 0px 10px 25px;
}

.navbar ul li a:hover {
text-decoration: none;
color: #FF0000;
padding: 10px 0px 10px 25px;
}

.current-page a
{
text-decoration: none;
color: #FF0000;
padding: 10px 0px 10px 25px;
background-image: url(nav_star_on-c-1.png);
_background-image: url(nav_star_on.gif);
background-repeat: no-repeat;
background-position: 0px 6px;
}
